				sqlFall_4 = "CASE WHEN WK1.F11 > 0 THEN WK4.F11/WK1.F11 * 100 ELSE 0 END,CASE WHEN WK1.F12 > 0 THEN WK4.F12/WK1.F12 * 100 ELSE 0 END,CASE WHEN WK1.F13 > 0 THEN WK4.F13/WK1.F13 * 100 ELSE 0 END,CASE WHEN WK1.F14 > 0 THEN WK4.F14/WK1.F14 * 100 ELSE 0 END,CASE WHEN WK1.F15 > 0 THEN WK4.F15/WK1.F15 * 100 ELSE 0 END,CASE WHEN WK1.F16 > 0 THEN WK4.F16/WK1.F16 * 100 ELSE 0 END,CASE WHEN WK1.F17 > 0 THEN WK4.F17/WK1.F17 * 100 ELSE 0 END,CASE WHEN WK1.F18 > 0 THEN WK4.F18/WK1.F18 * 100 ELSE 0 END,CASE WHEN WK1.F19 > 0 THEN WK4.F19/WK1.F19 * 100 ELSE 0 END,CASE WHEN WK1.F20 > 0 THEN WK4.F20/WK1.F20 * 100 ELSE 0 END,CASE WHEN WK1.F21 > 0 THEN WK4.F21/WK1.F21 * 100 ELSE 0 END,CASE WHEN WK1.F22 > 0 THEN WK4.F22/WK1.F22 * 100 ELSE 0 END,CASE WHEN WK1.F23 > 0 THEN WK4.F23/WK1.F23 * 100 ELSE 0 END,CASE WHEN WK1.F24 > 0 THEN WK4.F24/WK1.F24 * 100 ELSE 0 END,CASE WHEN WK1.F25 > 0 THEN WK4.F25/WK1.F25 * 100 ELSE 0 END,";
				sqlFall_5 = "CASE WHEN WK3.F11 > 0 THEN WK5.F11/WK3.F11 ELSE 0 END,CASE WHEN WK3.F12 > 0 THEN WK5.F12/WK3.F12 ELSE 0 END,CASE WHEN WK3.F13 > 0 THEN WK5.F13/WK3.F13 ELSE 0 END,CASE WHEN WK3.F14 > 0 THEN WK5.F14/WK3.F14 ELSE 0 END,CASE WHEN WK3.F15 > 0 THEN WK5.F15/WK3.F15 ELSE 0 END,CASE WHEN WK3.F16 > 0 THEN WK5.F16/WK3.F16 ELSE 0 END,CASE WHEN WK3.F17 > 0 THEN WK5.F17/WK3.F17 ELSE 0 END,CASE WHEN WK3.F18 > 0 THEN WK5.F18/WK3.F18 ELSE 0 END,CASE WHEN WK3.F19 > 0 THEN WK5.F19/WK3.F19 ELSE 0 END,CASE WHEN WK3.F20 > 0 THEN WK5.F20/WK3.F20 ELSE 0 END,CASE WHEN WK3.F21 > 0 THEN WK5.F21/WK3.F21 ELSE 0 END,CASE WHEN WK3.F22 > 0 THEN WK5.F22/WK3.F22 ELSE 0 END,CASE WHEN WK3.F23 > 0 THEN WK5.F23/WK3.F23 ELSE 0 END,CASE WHEN WK3.F24 > 0 THEN WK5.F24/WK3.F24 ELSE 0 END,CASE WHEN WK3.F25 > 0 THEN WK5.F25/WK3.F25 ELSE 0 END,";
				sqlFall_6 = "CASE WHEN WK4.F11 > 0 THEN WK5.F11/WK4.F11 ELSE 0 END,CASE WHEN WK4.F12 > 0 THEN WK5.F12/WK4.F12 ELSE 0 END,CASE WHEN WK4.F13 > 0 THEN WK5.F13/WK4.F13 ELSE 0 END,CASE WHEN WK4.F14 > 0 THEN WK5.F14/WK4.F14 ELSE 0 END,CASE WHEN WK4.F15 > 0 THEN WK5.F15/WK4.F15 ELSE 0 END,CASE WHEN WK4.F16 > 0 THEN WK5.F16/WK4.F16 ELSE 0 END,CASE WHEN WK4.F17 > 0 THEN WK5.F17/WK4.F17 ELSE 0 END,CASE WHEN WK4.F18 > 0 THEN WK5.F18/WK4.F18 ELSE 0 END,CASE WHEN WK4.F19 > 0 THEN WK5.F19/WK4.F19 ELSE 0 END,CASE WHEN WK4.F20 > 0 THEN WK5.F20/WK4.F20 ELSE 0 END,CASE WHEN WK4.F21 > 0 THEN WK5.F21/WK4.F21 ELSE 0 END,CASE WHEN WK4.F22 > 0 THEN WK5.F22/WK4.F22 ELSE 0 END,CASE WHEN WK4.F23 > 0 THEN WK5.F23/WK4.F23 ELSE 0 END,CASE WHEN WK4.F24 > 0 THEN WK5.F24/WK4.F24 ELSE 0 END,CASE WHEN WK4.F25 > 0 THEN WK5.F25/WK4.F25 ELSE 0 END,";
