		sbSQL.append("    CASE WHEN WK1.F09 > 0 THEN ROUND(WK3.F09/WK1.F09 * 100,2) ELSE 0 END,CASE WHEN WK1.F10 > 0 THEN ROUND(WK3.F10/WK1.F10 * 100,2) ELSE 0 END,");
