		sbSQL.append("  SELECT WK1.MI_KEY3,8,CASE WHEN WK1.F01 > 0 THEN ROUND(WK4.F01/WK1.F01 * 100,2) ELSE 0 END,CASE WHEN WK1.F02 > 0 THEN ROUND(WK4.F02/WK1.F02 * 100,2) ELSE 0 END,");
		sbSQL.append("    CASE WHEN WK1.F03 > 0 THEN ROUND(WK4.F03/WK1.F03 * 100,2) ELSE 0 END,CASE WHEN WK1.F04 > 0 THEN ROUND(WK4.F04/WK1.F04 * 100,2) ELSE 0 END,CASE WHEN WK1.F05 > 0 THEN ROUND(WK4.F05/WK1.F05 * 100,2) ELSE 0 END,");
