		sbSQL.append(" from M_T04_RFM_MIDASHI M "+sqljoin+" W_ALL J ON M.MI_KEY1 = J.KEY AND M.MI_KEY2 = ITEM");
		sbSQL.append(" WHERE "+ sqlKBN2 +sqlCate );
		sbSQL.append(" GROUP BY M.MI_KEY1, M.MI_KEY2,M.MIDASHI1,M.MIDASHI2 ");
